import heapq

def match(orders):
    trades = []
    buy_heap = []   # max-heap by price (stored as -price), then seq: (-price, seq, id)
    sell_heap = []  # min-heap by price, then seq: (price, seq, id)
    book = {}       # id -> dict(side, price, qty, seq)
    seq_counter = 0

    def clean(heap):
        while heap and (heap[0][2] not in book or book[heap[0][2]]['qty'] <= 0):
            heapq.heappop(heap)

    for order in orders:
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        else:  # market
            _, oid, side, qty = order
            price = None

        seq_counter += 1
        seq = seq_counter
        remaining = qty

        if side == 'buy':
            opp = sell_heap
            while remaining > 0:
                clean(opp)
                if not opp:
                    break
                p, s, sid = opp[0]
                if typ != 'market' and p > price:
                    break
                sorder = book[sid]
                trade_qty = min(remaining, sorder['qty'])
                trades.append([oid, sid, p, trade_qty])
                remaining -= trade_qty
                sorder['qty'] -= trade_qty
                if sorder['qty'] == 0:
                    del book[sid]
                    heapq.heappop(opp)

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining, 'seq': seq}
                heapq.heappush(buy_heap, (-price, seq, oid))

        else:  # side == 'sell'
            opp = buy_heap
            while remaining > 0:
                clean(opp)
                if not opp:
                    break
                negp, s, bid = opp[0]
                p = -negp
                if typ != 'market' and p < price:
                    break
                border = book[bid]
                trade_qty = min(remaining, border['qty'])
                trades.append([bid, oid, p, trade_qty])
                remaining -= trade_qty
                border['qty'] -= trade_qty
                if border['qty'] == 0:
                    del book[bid]
                    heapq.heappop(opp)

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining, 'seq': seq}
                heapq.heappush(sell_heap, (price, seq, oid))

    return trades

